// 1. TCC示例：库存预占，重点处理幂等、空回滚和悬挂
@Service
public class InventoryTccService {
    @Transactional
    public boolean tryDeduct(String xid, String branchId, String skuId, int quantity) {
        TccBranch branch = branchRepo.find(xid, branchId);
        if (branch != null && branch.isCancelled()) return false;
        if (branch != null && branch.isTried()) return true;

        Inventory inv = inventoryRepo.selectForUpdate(skuId);
        if (inv.getAvailable() < quantity) return false;
        inv.setAvailable(inv.getAvailable() - quantity);
        inv.setFrozen(inv.getFrozen() + quantity);
        inventoryRepo.update(inv);
        branchRepo.insertTried(xid, branchId, skuId, quantity);
        return true;
    }

    @Transactional
    public void confirmDeduct(String xid, String branchId) {
        TccBranch branch = branchRepo.findForUpdate(xid, branchId);
        if (branch == null || branch.isConfirmed()) return;
        if (branch.isCancelled()) return;

        Inventory inv = inventoryRepo.selectForUpdate(branch.getSkuId());
        inv.setFrozen(inv.getFrozen() - branch.getQuantity());
        inventoryRepo.update(inv);
        branchRepo.markConfirmed(xid, branchId);
    }

    @Transactional
    public void cancelDeduct(String xid, String branchId, String skuId, int quantity) {
        TccBranch branch = branchRepo.findForUpdate(xid, branchId);
        if (branch == null) {
            branchRepo.insertCancelled(xid, branchId, skuId, quantity);
            return;
        }
        if (branch.isCancelled() || branch.isConfirmed()) return;

        Inventory inv = inventoryRepo.selectForUpdate(branch.getSkuId());
        inv.setFrozen(inv.getFrozen() - branch.getQuantity());
        inv.setAvailable(inv.getAvailable() + branch.getQuantity());
        inventoryRepo.update(inv);
        branchRepo.markCancelled(xid, branchId);
    }
}

// 2. 本地消息表：业务写入和待投递消息在同一个本地事务
@Service
public class OrderService {
    @Transactional
    public OrderId createOrder(CreateOrderCmd cmd) {
        Order order = Order.create(cmd);
        orderRepo.save(order);

        LocalMessage msg = new LocalMessage();
        msg.setMessageId(UUID.randomUUID().toString());
        msg.setTopic("order-created");
        msg.setBizKey(order.getId().toString());
        msg.setPayload(JSON.toJSONString(order));
        msg.setStatus(MessageStatus.PENDING);
        localMessageRepo.save(msg);
        return order.getId();
    }
}

@Scheduled(fixedDelay = 1000)
public void pollAndSend() {
    List<LocalMessage> messages = localMessageRepo.lockPending(MessageStatus.PENDING, 100);
    for (LocalMessage msg : messages) {
        try {
            kafkaTemplate.send(msg.getTopic(), msg.getBizKey(), msg.getPayload()).get();
            msg.markSent();
            localMessageRepo.update(msg);
        } catch (Exception e) {
            msg.increaseRetryCount();
            if (msg.getRetryCount() >= 10) msg.markFailed();
            localMessageRepo.update(msg);
        }
    }
}

// 3. Seata AT模式：短事务可快速接入，但要关注全局锁冲突和undo_log
@GlobalTransactional(timeoutMills = 60000, name = "create-order")
public OrderId createOrder(CreateOrderCmd cmd) {
    Order order = Order.create(cmd);
    orderRepo.save(order);
    inventoryClient.deduct(cmd.getItems());
    return order.getId();
}
